Translate("zhCN", "elwynn-forest", {
	title = "艾尔文森林",
	aliases = { "艾尔文" },
	sections = {
		{
			title = "概述",
			text = [=[艾尔文森林是{link:kingdom-of-stormwind}暴风王国{/link}葱绿的心脏。橡树紧紧环绕着王都的白色城墙，林间分布着宁静的湖泊、{link:ginro-hearthkindle}金{/link}色的田野和古老的矿洞，世世代代养育着这个王国。在{link:stormwind-city}暴风城{/link}的居民看来，艾尔文一向是世上最安全的地方。如今这份信念正渐渐动摇。狼群一季比一季更靠近农场，矿洞中有怪事萌动，昔日只有商人和朝圣者往来的道路上，如今出没着盗贼。]=],
		},
		{
			title = "起源",
			text = [=[没有编年史记载第一批{link:humans}人类{/link}在艾尔文定居的年份。人们所知道的是，这片森林早在{link:dark-portal}黑暗之门{/link}开启之前许多个世纪就有人居住了。当古老的{link:arathor}阿拉索{/link}帝国结束了它漫长的统一，{link:arathi-highlands}阿拉希{/link}血脉中勇敢的家族南下寻找新的土地。他们在那里找到了丰饶的森林与河流，建立起一个名为{link:azeroth}艾泽拉斯{/link}的王国，并在其中心建起了一座名为{link:stormwind-city}暴风城{/link}的城市。艾尔文成了王国的粮仓与花园。在城市北边，{link:northshire-abbey}北郡修道院{/link}的教士守护着对{link:holy-light}圣光{/link}的信仰，他们的修道院成了圣光在南方最古老的家园之一。]=],
		},
		{
			title = "当今",
			text = [=[艾尔文已从战争的灰烬中重新生长起来，但防守薄弱。{link:varian-wrynn}瓦里安·乌瑞恩{/link}国王失踪了，没有人能说出他去了哪里。他不在的时候，大领主{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}以摄政王的身份统治，王国的力量分散在十几处动荡的边境上。{link:kobolds}狗头人{/link}占据了{link:fargodeep-mine}法戈第矿洞{/link}和{link:jasperlode-mine}玉石矿洞{/link}。{link:riverpaw-gnolls}河爪豺狼人{/link}越过南部边境前来劫掠。{link:defias-brotherhood}迪菲亚潜行者{/link}的强盗掠夺着靠近{link:westfall}西部荒野{/link}的农庄。{link:goldshire}闪金镇{/link}仅有的几位治安官已无法独自守住这片森林，他们欢迎任何愿意效力的刀剑。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:stormwind-city}暴风城{/link}的人民。{/b} 农夫、{link:eastvale-logging-camp}东谷{/link}的伐木工和山中的矿工留了下来，因为这片土地肥沃，也因为他们无处可去。
• {b}{link:northshire-abbey}北郡{/link}的神职人员与新兵。{/b} 在修道院里，牧师和圣骑士训练那些将要保卫王国的年轻男女。
• {b}{link:kobolds}狗头人{/link}。{/b} 他们在矿洞中挖掘。他们最怕黑暗，以野蛮的执着守护着自己的蜡烛。
• {b}{link:riverpaw-gnolls}河爪豺狼人{/link}。{/b} 他们从南方的丘陵和{link:redridge-mountains}赤脊山{/link}下来，贪图食物和战利品。
• {b}{link:defias-brotherhood}迪菲亚{/link}潜行者。{/b} 他们的队伍最初由那些曾重建暴风城的人组成，如今这些人用刀子夺取他们认为王室仍欠他们的东西。
• {b}鱼人。{/b} {link:murlocs}鱼人{/link}部族盘踞在{link:crystal-lake}水晶湖{/link}和{link:stone-cairn-lake}石碑湖{/link}的岸边，自有人记事以来便是如此。]=],
		},
		{
			title = "历史",
			text = [=[• {b}长久的和平。{/b} 世世代代，艾尔文几乎只知道收获与节庆。它的村庄因流经{link:stormwind-city}暴风城{/link}的贸易而富足。
• {b}第一次战争。{/b} 后来，{link:orcs}兽人{/link}{link:horde}部落{/link}穿过{link:dark-portal}黑暗之门{/link}而来，{link:azeroth}艾泽拉斯{/link}的土地最先燃起战火。{link:first-war}第一次战争{/link}中，部落烧毁了艾尔文的农场和森林，连{link:northshire-abbey}北郡修道院{/link}的神圣殿堂也未能逃过火焰。最终暴风城本身遭到洗劫，{link:llane-wrynn}莱恩·乌瑞恩{/link}国王死在了自己的城堡中。{link:anduin-lothar}安度因·洛萨{/link}爵士带领幸存者向北渡海前往{link:lordaeron}洛丹伦{/link}，国王年幼的儿子{link:varian-wrynn}瓦里安{/link}也随他们一同离去。
• {b}归来。{/b} {link:second-war}第二次战争{/link}之后，流亡者回到了家乡。他们重新种植森林，重建村庄。{link:edwin-vancleef}艾德温·范克里夫{/link}领导的{link:stonemasons-guild}石匠协会{/link}从废墟中重建了暴风城。当{link:house-of-nobles}贵族院{/link}拒绝支付石匠们的工钱时，石匠们在街头暴动。{link:tiffin-wrynn}蒂芬·乌瑞恩{/link}王后死于这场混乱之中。石匠们被逐出了城市，{link:defias-brotherhood}迪菲亚{/link}潜行者便从他们的怨恨中诞生了。
• {b}当今。{/b} 如今国王不在，军队远在他方，艾尔文只能依靠寥寥几位治安官和志愿者的勇气。]=],
		},
		{
			title = "森林传说",
			text = [=[• 在艾尔文的{link:kobolds}狗头人{/link}中，没有什么罪行比偷蜡烛更严重。每一个在地下干过活的矿工都知道这种偷窃之后会响起的那声叫喊。
• 马科伦家和斯通菲尔德家隔着同一道篱笆争斗了不知多少年，久到双方都记不清了。然而{link:goldshire}闪金镇{/link}的传闻说，马科伦家的一个女儿和斯通菲尔德家的一个儿子会在田野昏暗时秘密相会。
• {link:tower-of-azora}阿祖拉之塔{/link}耸立在森林东部。那里住着一位法师，艾尔文的普通百姓既不懂他的研究，也无意过问。
• 南方的农夫压低声音谈论{link:hogger}霍格{/link}。他是一个体型巨大、狡猾异常的{link:gnolls}豺狼人{/link}，悬赏他首级的告示已经挂了许多个季节，却一直无人领取。]=],
		},
	},
})

Translate("zhCN", "northshire-abbey", {
	title = "北郡修道院",
	aliases = { "北郡" },
	sections = {
		{
			title = "概述",
			text = [=[北郡修道院坐落在{link:stormwind-city}暴风城{/link}以北一座幽静{link:stranglethorn-vale}山谷{/link}的尽头。几个世纪以来，它一直是{link:holy-light}圣光{/link}的殿堂，教士们在这里祈祷、治疗，并保存他们信仰的古籍。年轻的{link:medivh}麦迪文{/link}曾在这里昏睡多年，任何治疗者都无法将他唤醒，修道院的修士们一直照料着他。{link:first-war}第一次战争{/link}中，{link:horde}部落{/link}烧毁了它，但信徒们回来了，重新筑起了它的围墙。如今这里是一处训练场。新兵们来这里学习剑术、法术和祈祷，然后被派往需要他们的森林。]=],
		},
		{
			title = "山谷",
			text = [=[{link:stranglethorn-vale}山谷{/link}已不再宁静。{link:kobolds}狗头人{/link}挖进了修道院上方的回音山矿洞。戴着红色头巾的盗贼潜伏在北郡农场的葡萄藤间，他们的首领在山谷东缘有一间棚屋。狼群从山上下来。北郡的修士们已经明白，即使是圣地也必须有人守卫。]=],
		},
	},
})

Translate("zhCN", "goldshire", {
	title = "闪金镇",
	sections = {
		{
			title = "概述",
			text = [=[闪金镇是{link:elwynn-forest}艾尔文{/link}的{link:the-crossroads}十字路口{/link}。它的道路向北通往修道院，向南通往农场，向东通往伐木营地，向西通往{link:westfall}西部荒野{/link}。镇中心矗立着狮王之傲旅店，自镇上最年长的居民记事起，法{link:farmer-ray}雷{/link}一家就在那里为旅人斟酒。镇上有一位铁匠、一座马厩和一家药剂店。这里也是{link:marshal-dughan}治安官杜汉{/link}的驻地，他手下的寥寥几名士兵必须为整片森林的安全负责。]=],
		},
		{
			title = "当下",
			text = [=[旅店里充斥着各种传闻。商人们谈论着从矿洞收购的{link:ginro-hearthkindle}金{/link}粉，谈论着在湖岸变得胆大妄为的{link:murlocs}鱼人{/link}，谈论着南方大路上的{link:gnolls}豺狼人{/link}。闪金镇最年长的居民仍记得{link:first-war}第一次战争{/link}的硝烟。年轻一代正开始明白长辈们的意思。]=],
		},
	},
})

Translate("zhCN", "fargodeep-mine", {
	title = "法戈第矿洞",
	aliases = { "法戈第" },
	sections = {
		{
			title = "概述",
			text = [=[法戈第曾是王室的一座{link:ginro-hearthkindle}金{/link}矿。它位于{link:elwynn-forest}艾尔文{/link}南部的丘陵中，介于斯通菲尔德家和马科伦家的土地之间。矿工们离开后，{link:kobolds}狗头人{/link}来了。如今它的坑道里闪烁着狗头人巢穴的烛光，据说狗头人{link:goldtooth}金牙{/link}在矿洞深处囤积着偷来的财宝。不管狗头人在朝什么方向挖，他们都挖得十分起劲。]=],
		},
	},
})

Translate("zhCN", "jasperlode-mine", {
	title = "玉石矿洞",
	aliases = { "玉石" },
	sections = {
		{
			title = "概述",
			text = [=[玉石矿洞位于东部的丘陵中，在{link:tower-of-azora}阿祖拉之塔{/link}以北。它曾是为{link:stormwind-city}暴风城{/link}的{link:the-cauldron}熔炉{/link}供矿的矿洞之一。如今{link:kobolds}狗头人{/link}占据着它上层的坑道。再往深处，连狗头人都不愿意去的地方，巨大的矿洞蜘蛛在黑暗中结网。从玉石矿洞逃出来的矿工谈起蜘蛛比谈起狗头人更多。]=],
		},
	},
})

Translate("zhCN", "tower-of-azora", {
	title = "阿祖拉之塔",
	aliases = { "阿祖拉" },
	sections = {
		{
			title = "概述",
			text = [=[阿祖拉之塔高耸于{link:elwynn-forest}艾尔文{/link}东部的树林之上。它是法师{link:theocritus}塞欧克瑞图斯{/link}及侍奉他的{link:gnomes}侏儒{/link}们的居所。在塔的最高一层，一件名为阿祖拉之眼的占卜装置远眺东方，望向{link:redridge-mountains}赤脊山{/link}的{link:tower-of-ilgalar}伊尔加拉之塔{/link}。那里住着术士{link:morganth}大魔导师杜内{/link}，塞欧克瑞图斯发誓要监视并挫败他的黑暗研究。森林的居民对这两座塔都敬而远之。]=],
		},
	},
})

Translate("zhCN", "brackwell-pumpkin-patch", {
	title = "布莱克威尔南瓜田",
	aliases = { "布莱克威尔" },
	sections = {
		{
			title = "概述",
			text = [=[布莱克威尔农场位于{link:elwynn-forest}艾尔文{/link}东南部，曾有一户人家在这里种出了闻名整片森林的南瓜。布莱克威尔一家已经不在了，没有人能说出他们的下落。如今{link:defias-brotherhood}迪菲亚潜行者{/link}占据着这座农场。据说从{link:kobolds}狗头人{/link}矿洞中夺来的{link:ginro-hearthkindle}金{/link}子会经过这里，送到一名被称为收集者的迪菲亚特工手中。布莱克威尔家只留下了一件宝贝：公主，他们的获奖母猪，它靠吃邻居的蔬菜长得巨大无比。]=],
		},
	},
})

Translate("zhCN", "eastvale-logging-camp", {
	title = "东谷伐木场",
	aliases = { "东谷" },
	sections = {
		{
			title = "概述",
			text = [=[东谷是{link:elwynn-forest}艾尔文{/link}的伐木营地，位于森林东缘、通往{link:redridge-mountains}赤脊山{/link}的大路附近。它的伐木工供应了重建{link:stormwind-city}暴风城{/link}的木材，至今每一季仍有马车向西驶去。营地时刻受到狼和熊的威胁。{link:guard-thomas}卫兵托马斯{/link}把守着西边的桥，{link:marshal-haggard}治安官哈迦德{/link}的旧宅就在附近。]=],
		},
	},
})

Translate("zhCN", "stone-cairn-lake", {
	title = "石碑湖",
	sections = {
		{
			title = "概述",
			text = [=[石碑湖是森林东北部环绕着一座林木葱郁小岛的一圈湖水。湖岸上坐落着英雄哨岗，那里的一座石堆纪念着在{link:first-war}第一次战争{/link}中死去的{link:goldshire}闪金镇{/link}及其周边农场的男男女女。这是一个哀悼之地。它已不再是一个安宁之地：叛变的巫师占据了小岛，{link:murlocs}鱼人{/link}在南岸捕猎。]=],
		},
	},
})

Translate("zhCN", "maclure-vineyards-and-stonefield-farm", {
	title = "马科伦农场与斯通菲尔德农场",
	aliases = { "马科伦农场", "斯通菲尔德农场" },
	sections = {
		{
			title = "概述",
			text = [=[在{link:elwynn-forest}艾尔文{/link}南部，两座农场分别坐落在一条狭长地带的两侧。东边生长着马科伦家的葡萄藤。西边是斯通菲尔德家的田地和房屋。两家人争斗的时间比他们任何一个孩子能记得的都要长，起因早已被埋没在辱骂、偷窃和摔门之下。然而葡萄园与农场之间有一条静谧的小路，并不是每个走在上面的人都怀着怒气。]=],
		},
	},
})

Translate("zhCN", "crystal-lake", {
	title = "水晶湖",
	sections = {
		{
			title = "概述",
			text = [=[水晶湖位于{link:goldshire}闪金镇{/link}以东，正如其名，平静而清澈。湖水滋养着一种像玻璃一样闪闪发光的稀有海藻，药剂师因其奇特的性质而珍视它。湖中的{link:murlocs}鱼人{/link}对它看守得十分严密。曾在这里撒网的渔夫，如今都待在对岸。]=],
		},
	},
})

Translate("zhCN", "westbrook-garrison", {
	title = "西泉要塞",
	aliases = { "西泉" },
	sections = {
		{
			title = "概述",
			text = [=[西泉要塞守卫着{link:elwynn-forest}艾尔文{/link}的西缘，森林在那里让位于{link:westfall}西部荒野{/link}的田野。它的营房是为维护边境的和平而建的。如今它们什么都难以维持。盗贼从西边来，林边空地的{link:riverpaw-gnolls}河爪豺狼人{/link}从南边来劫掠。要塞的告示板上挂着一张每个士兵都背得出来的告示：悬赏{link:hogger}霍格{/link}的首级。]=],
		},
	},
})

Translate("zhCN", "marshal-mcbride", {
