			title = "概述",
			text = [=[治安官道格拉斯·玛克布莱德指挥着{link:northshire-abbey}北郡修道院{/link}的新兵。每一位{link:stormwind-city}暴风城{/link}的新守卫者都要先经过他的手。他必须把农夫的儿子和书记员的女儿训练成士兵，而且必须在王国军队远在他方、{link:stranglethorn-vale}山谷{/link}本身也受到威胁的情况下做到这一点。]=],
