	sections = {
		{
			title = "概述",
			text = [=[野营是一门古老的旅途技艺：在野外生起一堆火，与人分享，在继续旅程之前在火旁休息。{link:azeroth}艾泽拉斯{/link}各地的旅人一向知道，在一堆好火旁度过的一夜，可能决定了是能抵达下一座城镇，还是永远到不了。]=],
		},
		{
			title = "火与手艺",
			text = [=[营地始于一堆营火，由懂得烹饪技艺的人生起。其他旅人随后可以各按自己所知的手艺为它添砖加瓦。铁匠架起一个磨刀轮。制皮匠搭起一顶帐篷。炼{link:ginro-hearthkindle}金{/link}术士、附魔师、矿工或裁缝各自带来一样属于自己的东西：一口法力之井、一把附魔鲁特琴、一块磁石、一面本族的旗帜。这些作品中最伟大的，是依照各门手艺的大师所保存的图纸建造的，据说其中一些图纸落在了危险的敌人手中。]=],
		},
		{
			title = "火边的习俗",
			text = [=[按照习俗，每位旅人只为共享的营火添加一件作品，同一堆火旁不会出现两次同样的手艺。在这样的火旁坐上一会儿的人，起身时会精神焕发，并在路上把这份益处带在身边好几个小时。]=],
		},
	},
})
